insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 1, 'Which flareToValue function answers the studio question "what is in this gas, and how much liquid could it give"?', '["creditSensitivity", "screenRoute", "characteriseGas", "routeEconomics"]'::jsonb, 2, 'The digest''s table of questions pairs that question with characteriseGas. creditSensitivity answers whether the project needs carbon credits to clear its hurdle, screenRoute answers which way of selling the gas it allows, and routeEconomics answers what a route makes, earns and costs in a year.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 2, 'What does the digest''s export table count for flareToValue?', '["7 exported functions and 10 exported constants and tables", "10 exported functions and 9 exported constants and tables", "10 exported functions and 7 exported constants and tables", "10 exported functions and 10 exported constants and tables"]'::jsonb, 0, 'The flareToValue row reads 7 functions (abatement, characteriseGas, compareRoutes, creditSensitivity, routeEconomics, screenRoute, yieldCeiling) and 10 constants and tables. 10 functions and 9 constants and tables is the lpgCng row.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 3, 'lpgCng calls three modules and writes none of the three itself. What does it call terminalDepot for?', '["The gas Z factor, for the gas in a bank", "The compressor train, for the station compressor", "The power law, for scaling a plant''s capital", "The loading-rack queue, for its carousel and forecourt"]'::jsonb, 3, 'The digest says lpgCng calls the loading-rack queue in terminalDepot for its carousel and forecourt, the gas Z factor in production/gasProperties and the compressor train in facilities/compression. The capital power law is in modularRefinery, which flareToValue uses.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 4, 'SCF_PER_LBMOL reads 379.49. What does the constant count?', '["Pounds in one kilogram", "Standard cubic feet in one lb-mol", "US gallons in one cubic foot", "Cubic metres in one standard cubic foot"]'::jsonb, 1, 'The constants table gives SCF_PER_LBMOL 379.49, standard cubic feet in one lb-mol. Pounds in one kilogram is LB_PER_KG (2.20462262), US gallons in one cubic foot is GAL_PER_FT3 (7.480519) and cubic metres in one standard cubic foot is lpgCng''s M3_PER_SCF (0.02831684659).'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 5, 'One Mscf of methane carries 19.1757 kg and one Mscf of carbon dioxide carries 52.6038 kg. What does the digest say the two rows hold the same?', '["The mass in the Mscf", "The count of moles", "The molar mass behind the row", "The typical heating value of the gas"]'::jsonb, 1, 'A standard cubic foot counts gas at 60 F and 14.696 psia, so every row is the same count of moles and the mass follows the molar mass: 16.043 lb/lbmol for methane and 44.01 for carbon dioxide. The heating values differ too, 1010 Btu/scf for methane against 0 for carbon dioxide.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 6, 'How does the digest say kgPerMscf is built from the engine''s constants?', '["1000 times SCF_PER_LBMOL gives the lb-mol, times the molar mass gives pounds, times LB_PER_KG gives kilograms", "1000 over SCF_PER_LBMOL gives the lb-mol, times GAL_PER_FT3 gives cubic feet, over LB_PER_KG gives kilograms", "SCF_PER_LBMOL over 1000 gives the lb-mol, times the molar mass gives pounds, over LB_PER_KG gives kilograms", "1000 over SCF_PER_LBMOL gives the lb-mol, times the molar mass gives pounds, over LB_PER_KG gives kilograms"]'::jsonb, 3, 'The lb-mol in one Mscf is 1000 over SCF_PER_LBMOL, the pounds are that times the mole-weighted molar mass, and the kilograms are the pounds over LB_PER_KG. Done on the constants it gives 19.1757 for methane and 52.6038 for carbon dioxide, a difference of 0.0000 from the engine on both rows.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 7, 'Propane''s molar mass in the reference is 44.096 lb/lbmol. What kgPerMscf does characteriseGas give for one Mscf of pure propane?', '["52.6038", "52.7066", "35.9417", "33.4842"]'::jsonb, 1, 'Pure propane gives 52.7066 kg in one Mscf. 52.6038 is pure carbon dioxide at 44.01 lb/lbmol, 35.9417 is pure ethane at 30.07 and 33.4842 is pure nitrogen at 28.014.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 8, 'Which rows of GAS_COMPONENT_REFERENCE are marked inert?', '["N2 alone", "CO2 alone", "N2 and CO2", "C1, N2 and CO2"]'::jsonb, 2, 'The inert column reads true on N2 (Nitrogen) and CO2 (Carbon dioxide) and false on every other row, C1 included. Both inert rows carry a typical heating value of 0.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 9, 'The CO2 row carries one carbon per molecule and is marked inert. What does the digest say about that carbon?', '["It is left out of the carbon per mole, because the row is marked inert.", "It is counted as a fuel carbon, at the typical heating value of methane.", "It is counted at zero in the carbon per mole, as nitrogen''s row is.", "It is counted when the carbon per mole is counted, and CO2 is no fuel."]'::jsonb, 3, 'The digest''s sentence on the row: its carbon is counted when the carbon per mole is counted, and it is not a fuel. The CO2 row''s typical heating value is 0, and nitrogen carries 0 carbon per molecule where CO2 carries 1.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 10, 'The engine''s note on GAS_COMPONENT_REFERENCE calls two of its columns definitional. Which two?', '["Molar masses and carbon numbers", "Heating values and liquid densities", "Molar masses and heating values", "Carbon numbers and liquid densities"]'::jsonb, 0, 'The note: "Molar masses and carbon numbers are definitional. Heating values and liquid densities are typical: the gas analysis and the certificate govern, and a measured value should replace these."'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 11, 'Which code does GAS_COMPONENT_REFERENCE label "Pentanes plus", and how many carbon per molecule does its row carry?', '["NC4, with 4", "C5, with 5", "C5, with 4", "IC4, with 5"]'::jsonb, 1, 'The C5 row is labelled Pentanes plus and carries 5 carbon per molecule. IC4 (Iso-butane) and NC4 (n-Butane) each carry 4.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 12, 'EGBEMA''s sheet is typed short, summing to 0.9850. What does characteriseGas do with it?', '["It refuses the sheet: the gas composition sums to nothing.", "It scales the fractions to one and says so in a note.", "It uses the fractions as typed and reports their raw sum.", "It adds the shortfall to methane and leaves the rest as typed."]'::jsonb, 1, 'The normalisationNote reads: "The mole fractions summed to 0.985 and were scaled to one. Check the analysis if that was not intended." Every normalised figure on the short sheet differs from its typed figure, C1 0.73 becoming 0.7411.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 13, 'On the short EGBEMA sheet, which fractions does the engine work with for methane and nitrogen?', '["C1 0.7411 and N2 0.0183", "C1 0.7420 and N2 0.0180", "C1 0.7411 and N2 0.018", "C1 0.73 and N2 0.018"]'::jsonb, 0, 'The normalised short-sheet column reads C1 0.7411 and N2 0.0183: the nitrogen moves from its typed 0.018 as the methane moves from 0.73. C1 0.7420 and N2 0.0180 are the full sheet''s normalised figures.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 14, 'Which function do the studios use to answer "does the project need carbon credits to clear its hurdle"?', '["compareRoutes", "routeEconomics", "screenRoute", "creditSensitivity"]'::jsonb, 3, 'creditSensitivity is the function paired with the credits question. The bid, a route''s year and the selling routes go to the other three.'),
  ('gasvalue', 'beginner', 'module', 'm01-what-is-being-flared', 15, 'Which of these constants is one that lpgCng exports?', '["SCF_PER_LBMOL", "RICHNESS_GPM", "PSI_PER_BAR", "FLARE_MOLAR_MASS"]'::jsonb, 2, 'PSI_PER_BAR is in lpgCng''s list of 9, with M3_PER_SCF and KJ_PER_KWH. SCF_PER_LBMOL, RICHNESS_GPM and FLARE_MOLAR_MASS are three of flareToValue''s 10.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 1, 'On what basis does characteriseGas blend a gas''s heating value?', '["Mass-weighted over the normalised analysis, inerts included", "Mole-weighted over the normalised analysis, inerts included", "Mole-weighted over the hydrocarbons alone, rescaled to one", "Weighted by liquid volume over the recoverable components"]'::jsonb, 1, 'Every property in SECTION 5 is a mole-weighted sum over the normalised analysis, and the heating value is the mole-weighted heating value. The mass weighting (1537.2878 Btu/scf on EGBEMA) and the hydrocarbons alone (1308.6069) are the two shortcuts the digest prints beside the engine''s 1248.4110.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 2, 'What heating value, in Btu/scf, does characteriseGas return for EGBEMA?', '["1537.2878", "1308.6069", "1210.7800", "1248.4110"]'::jsonb, 3, 'ghvBtuScf for EGBEMA is 1248.4110. 1537.2878 is the same heating values weighted by mass, 1308.6069 is the engine asked about the hydrocarbons alone, and 1210.7800 is the studio''s opening gas.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 3, 'Which mixture molar mass, in lb/lbmol, sits behind the 25.4954 kg that one Mscf of the studio gas weighs?', '["21.3303", "22.3436", "17.5880", "16.043"]'::jsonb, 0, 'molarMassLbLbmol reads 21.3303 on the studio''s opening gas. 22.3436 is EGBEMA''s, 17.5880 is OGUTA''s and 16.043 is pure methane''s reference molar mass.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 4, 'EGBEMA''s inertMoleFraction is 0.0460. Which normalised fractions does the engine sum to get it?', '["carbon dioxide at 0.0280 plus pentanes plus at 0.0120", "nitrogen at 0.0180 plus pentanes plus at 0.0120", "nitrogen at 0.0180 plus carbon dioxide at 0.0280", "nitrogen, carbon dioxide and methane at 0.7420"]'::jsonb, 2, 'inertMoleFraction is the sum of the normalised fractions of the components the reference marks inert, nitrogen and CO2. The digest''s table prints N2 0.0180, CO2 0.0280, N2 plus CO2 0.0460 and the engine''s 0.0460. C5 and C1 are not marked inert.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 5, 'OGUTA''s carbonPerMol is 1.0580 and its hydrocarbonCarbonPerMol is 1.0430. What does the digest say carbonPerMol minus hydrocarbonCarbonPerMol is, in every row?', '["The CO2 mole fraction", "The inert mole fraction", "The nitrogen mole fraction", "The ethane mole fraction"]'::jsonb, 0, 'In every row, carbonPerMol minus hydrocarbonCarbonPerMol is the CO2 mole fraction: the only carbon that cannot burn is the carbon already in CO2. OGUTA''s co2MoleFraction is 0.0150, and its inertMoleFraction, 0.0270, also counts nitrogen, which carries no carbon.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 6, 'Which of EGBEMA''s two carbon counts includes the carbon already in CO2?', '["hydrocarbonCarbonPerMol, 1.3320", "Both, as CO2 carries one carbon per molecule", "Neither, as the reference marks CO2 inert", "carbonPerMol, 1.3600"]'::jsonb, 3, 'The carbon per mole counts every carbon atom, the CO2''s included; the hydrocarbon carbon per mole counts only the carbon that can burn. EGBEMA reads 1.3600 and 1.3320, and the gap is its CO2 mole fraction, 0.0280.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 7, 'How many kilograms does characteriseGas give for one Mscf of OGUTA?', '["26.7066", "25.4954", "21.0224", "19.1757"]'::jsonb, 2, 'OGUTA''s kgPerMscf is 21.0224, at a molar mass of 17.5880 lb/lbmol. 26.7066 is EGBEMA, 25.4954 the studio''s opening gas and 19.1757 one Mscf of pure methane.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 8, 'One Mscf of EGBEMA carries 26.7066 kg and one Mscf of OGUTA 21.0224 kg. By which figure of each gas does the engine''s mass rule multiply the moles in a thousand standard cubic feet?', '["Its heating value: 1248.4110 and 1035.6050 Btu/scf", "Its molar mass: 22.3436 and 17.5880 lb/lbmol", "Its carbon per mole: 1.3600 and 1.0580", "Its methane fraction: 0.7420 and 0.9250"]'::jsonb, 1, 'The mass in one Mscf is the moles in a thousand standard cubic feet times the molar mass. EGBEMA''s molarMassLbLbmol is 22.3436 and OGUTA''s is 17.5880.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 9, 'The digest probes a gas of methane 0.9 and propane 0.1, with propane''s carbon number left blank. What carbonPerMol does the engine report?', '["A refusal naming C3, since no carbon number was typed", "None: carbonPerMol is left null and named missing", "1.2000 for hydrocarbonCarbonPerMol, carbonPerMol null", "1.2000, as with 3 typed"]'::jsonb, 3, 'A hydrocarbon typed without a carbon number takes it from the reference by its code. Both probe rows, propane''s carbon number typed and left blank, read carbonPerMol 1.2000 and hydrocarbonCarbonPerMol 1.2000.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 10, 'An analysis carries an unknown code, XX, with no carbon number. What does characteriseGas answer?', '["REFUSED: No carbon number for XX. The flare''s CO2 is counted atom by atom, so it is not assumed.", "REFUSED: A characterised gas is required.", "It takes XX at one carbon per molecule and reports the gas with a note saying so.", "It leaves XX out of the carbon per mole and scales the remaining fractions to one."]'::jsonb, 0, 'The refusal table prints that sentence for the unknown code XX with no carbon number. "A characterised gas is required" is abatement''s answer to a gas the analysis refused.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 11, 'Which probe gets the answer "REFUSED: Every component needs a mole fraction."?', '["Every mole fraction typed as zero", "Methane 1.1 and ethane -0.1", "Methane typed as a blank ('''')", "Code XX with no carbon number"]'::jsonb, 2, 'The blank mole fraction gets that sentence. A sheet of zeros gets "REFUSED: The gas composition sums to nothing.", methane 1.1 with ethane -0.1 gets "REFUSED: A mole fraction cannot be negative." and XX gets the carbon number refusal.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 12, 'What methaneMoleFraction does characteriseGas report for OGUTA?', '["0.7420", "0.9250", "0.7800", "0.7411"]'::jsonb, 1, 'SECTION 5 prints OGUTA''s methane at 0.9250; the other three belong to EGBEMA, the studio gas and the short sheet as scaled.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 13, 'The engine is asked about EGBEMA''s hydrocarbons alone, inerts left out and the rest scaled to one. What does the digest print for that heating value?', '["1308.6069 Btu/scf, 60.1959 below the engine''s", "1537.2878 Btu/scf, 288.8768 above the engine''s", "1248.4110 Btu/scf, the same as the engine''s", "1308.6069 Btu/scf, 60.1959 above the engine''s"]'::jsonb, 3, 'The hydrocarbons-alone row reads 1308.6069 with 60.1959 in the "minus the engine''s" column, and the digest says both shortcuts read higher than the engine on this gas. 1537.2878 with 288.8768 is the mass-weighted row, and 1248.4110 is the engine on moles.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 14, 'Which gas does the digest print with carbonPerMol 1.3000 and hydrocarbonCarbonPerMol 1.2800?', '["The studio''s opening gas, with CO2 0.0200", "EGBEMA, with CO2 0.0280", "OGUTA, with its CO2 mole fraction at 0.0150", "The propane probe, methane 0.9 and propane 0.1"]'::jsonb, 0, 'The studio''s opening gas reads 1.3000 and 1.2800 with a co2MoleFraction of 0.0200. EGBEMA reads 1.3600 and 1.3320, OGUTA 1.0580 and 1.0430, and the propane probe 1.2000 and 1.2000.'),
  ('gasvalue', 'beginner', 'module', 'm02-the-gas-by-the-mole', 15, 'The studio''s opening gas carries N2 0.02 and CO2 0.02. What inertMoleFraction does the engine report for it?', '["0.0200", "0.0460", "0.0400", "0.0270"]'::jsonb, 2, 'The studio''s row prints N2 plus CO2 0.0400 beside the engine''s 0.0400. Its co2MoleFraction alone is 0.0200; 0.0460 and 0.0270 belong to EGBEMA and OGUTA.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 1, 'The engine''s basis sentence for gpmC2Plus and gpmC3Plus says gallons per Mscf follows from three things. Which three?', '["The moles in a thousand cubic feet, the carbon per molecule and the liquid density", "The heating value, the molar mass and the liquid density of each component", "The mass in one Mscf, GAL_PER_FT3 and the richness edges in RICHNESS_GPM", "The moles in a thousand cubic feet, the molar mass and the liquid density"]'::jsonb, 3, '"Derived from the composition and the component liquid densities: gallons per Mscf follows from the moles in a thousand cubic feet, the molar mass and the liquid density."'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 2, 'How many gallons of ethane and heavier per Mscf does characteriseGas report for EGBEMA?', '["3.2205", "5.9942", "5.0897", "2.7737"]'::jsonb, 1, 'EGBEMA''s gpmC2Plus is 5.9942. 3.2205 is its gpmC3Plus (propane and heavier), 2.7737 is the ethane between the two, and 5.0897 is the studio opening gas''s gpmC2Plus.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 3, 'OGUTA reads gpmC2Plus 1.3157 and gpmC3Plus 0.4890. What does the digest name the column between them, and what does it print for OGUTA?', '["The ethane, 0.8268", "The ethane, 2.7737", "The propane, 0.8268", "The methane, 0.8268"]'::jsonb, 0, 'The column is gpmC2Plus minus gpmC3Plus, and the digest heads it "the ethane": 0.8268 on OGUTA, 2.7737 on EGBEMA and 2.4003 on the studio''s opening gas. Methane is not recoverable as NGL and is in neither cut.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 4, 'Which components does gpmC3Plus sum over?', '["C2, C3, IC4, NC4 and C5", "C3, IC4 and NC4, pentanes plus left out", "C3, IC4, NC4 and C5", "C1, C2, C3, IC4, NC4 and C5"]'::jsonb, 2, 'gpmC3Plus sums propane to pentanes plus; gpmC2Plus sums ethane to pentanes plus. The per-component table marks C3, IC4, NC4 and C5 true in gpmC3Plus and C2 true only in gpmC2Plus.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 5, 'A gas reads gpmC3Plus of exactly 2.5000. Which richness word does the engine give it?', '["moderate", "lean", "rich", "null"]'::jsonb, 2, 'RICHNESS_GPM puts the change from moderate to rich at gpmC3Plus 2.5000, and a gas at or above the upper edge reads rich. The word reads null when gpmC3Plus is itself missing, as with propane''s density blank.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 6, 'Which is the full set of components that carry no liquid density in the reference and are summed in neither liquid cut?', '["Methane, nitrogen and carbon dioxide", "Methane alone", "Nitrogen and carbon dioxide", "Methane, ethane and nitrogen"]'::jsonb, 0, 'The per-component table reads recoverable false, in neither cut and gal/Mscf none on C1, N2 and CO2, and the reference prints liquid density none on the same three rows. C2 is recoverable and is in gpmC2Plus at 2.7737 gal/Mscf on EGBEMA.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 7, 'Which gas reads lean, and on which figure is the word read?', '["OGUTA, at gpmC2Plus 1.3157", "The studio''s opening gas, at gpmC3Plus 2.6894", "EGBEMA, at gpmC3Plus 3.2205", "OGUTA, at gpmC3Plus 0.4890"]'::jsonb, 3, 'The richness word is read off gpmC3Plus. OGUTA''s 0.4890 is below the lower edge of 1.0000 and reads lean; EGBEMA at 3.2205 and the studio''s opening gas at 2.6894 read rich.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 8, 'EGBEMA is analysed with propane''s liquid density left blank. What does characteriseGas return for the liquids?', '["gpmC2Plus 2.7737 from the ethane alone, gpmC3Plus null, missingLiquidDensity C3", "gpmC2Plus null, gpmC3Plus null, richness null, missingLiquidDensity C3", "gpmC2Plus 5.9942, gpmC3Plus 3.2205, richness rich, missingLiquidDensity none", "REFUSED, since every recoverable component needs a liquid density"]'::jsonb, 1, 'The probe row prints gpmC2Plus null, gpmC3Plus null, richness null and missingLiquidDensity C3, with ghvBtuScf still 1248.4110. A blank density leaves the liquids content and the richness word missing; neither is a partial sum.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 9, 'EGBEMA is analysed with n-butane''s heating value left blank. What does ghvBtuScf read?', '["null, with a ghvNote beside it", "1248.4110, the value with every heating value typed", "an average over the rest", "REFUSED, with no figure"]'::jsonb, 0, 'The n-butane probe row prints ghvBtuScf null with a ghvNote, while its gallon figures and richness word read as typed.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 10, 'The n-butane heating value probe on EGBEMA: which gallon figures and richness word come back?', '["null and null, richness null", "null, with missingLiquidDensity NC4", "5.0897 and 2.6894 gal/Mscf, rich", "5.9942 and 3.2205 gal/Mscf, rich"]'::jsonb, 3, 'The n-butane heating value probe prints gpmC2Plus 5.9942, gpmC3Plus 3.2205, richness rich and missingLiquidDensity none, the same liquids as EGBEMA as typed. 5.0897 and 2.6894 are the studio''s opening gas.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 11, 'What does the digest print for EGBEMA''s propane and heavier mass against its whole mass in one Mscf?', '["5.5819 of 25.4954 kg, a share of 0.2189", "6.6647 of 26.7066 kg, a share of 0.2496", "6.6647 of 26.7066 kg, a share of 0.2189", "0.9798 of 21.0224 kg, a share of 0.0466"]'::jsonb, 1, 'EGBEMA''s row reads kgPerMscf 26.7066, c3PlusKgPerMscf 6.6647 and c3PlusKgPerMscf over kgPerMscf 0.2496. 5.5819 of 25.4954 at 0.2189 is the studio''s opening gas and 0.9798 of 21.0224 at 0.0466 is OGUTA.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 12, 'c3PlusKgPerMscf is read on the probe that blanks propane''s density. What does EGBEMA''s read?', '["null, beside gpmC3Plus null", "null, with missingLiquidDensity C3", "6.6647 kg/Mscf", "a partial mass, propane left out"]'::jsonb, 2, 'The mass ceiling reads no liquid density. With propane''s density blank, c3PlusKgPerMscf is still 6.6647 and kgPerMscf 26.7066, while the gallon figures read null.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 13, 'In EGBEMA''s per-component gallons, which row gives 1.7019 gal/Mscf, and which cuts is it in?', '["C3, in both gpmC2Plus and gpmC3Plus", "C2, in gpmC2Plus only", "C3, in gpmC3Plus only", "NC4, in both cuts"]'::jsonb, 0, 'The C3 row reads 1.7019 gal/Mscf and true in both cuts. C2 reads 2.7737 and is in gpmC2Plus only; NC4 reads 0.6602.'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 14, 'RICHNESS_GPM exports the edges of a screening word. Beside that word, what does the digest say governs a route''s liquids?', '["The RICHNESS_GPM edge the gas sits above", "The richness word, read off gpmC3Plus", "gpmC2Plus, read against the same edges", "The route''s own liquids limit"]'::jsonb, 3, 'The digest reads the richness word off gpmC3Plus against RICHNESS_GPM and calls it "a screening word; a route''s own liquids limit governs".'),
  ('gasvalue', 'beginner', 'module', 'm03-the-liquids-in-the-gas', 15, 'Where does the richness word change from lean to moderate?', '["At gpmC3Plus 2.5000", "At gpmC3Plus 1.0000", "At gpmC2Plus 1.0000", "At gpmC2Plus 2.5000"]'::jsonb, 1, 'The RICHNESS_GPM table puts lean to moderate at gpmC3Plus 1.0000 and moderate to rich at 2.5000. A gas at or above the lower edge reads moderate. The word is read off gpmC3Plus.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 1, 'In the engine''s 40 CFR 98.233(n) basis sentence, what does the combustion efficiency multiply?', '["The carbon per mole, the CO2''s included", "The methane in the gas", "The hydrocarbon carbon", "The CO2 in the gas"]'::jsonb, 2, '"CO2 = the CO2 in the gas plus the combustion efficiency times the hydrocarbon carbon; CH4 = the methane in the gas times one less the destruction efficiency."'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 2, 'Which methane does the engine count as escaping the flare?', '["The methane in the gas times one less the destruction efficiency", "Every unburned carbon atom, counted as methane", "The methane in the gas times one less the combustion efficiency", "The hydrocarbon carbon times one less the destruction efficiency"]'::jsonb, 0, 'The methane that escapes is the methane in the gas times one less the destruction efficiency. Every unburned carbon counted as methane is the shortcut the digest prints beside the engine at 2083.055 t/yr against the engine''s 1136.490.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 3, 'What does the digest print for EGBEMA''s methane if every unburned carbon atom is counted as methane, and over the engine''s figure?', '["3788.301 t/yr, 1.8329 over the engine''s 1136.490", "2083.055 t/yr, 1.8329 over the engine''s 1136.490", "2083.055 t/yr, 1.8329 over the engine''s 1531.658", "1531.658 t/yr, 1.0000 over the engine''s 1136.490"]'::jsonb, 1, 'The shortcut row reads 2083.055 t/yr and 1.8329 in the "over the engine''s" column; the engine''s row reads 1136.490 and 1.0000. 3788.301 is the engine''s methane at a destruction efficiency of 0.9, and 1531.658 is the all-methane probe.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 4, 'What does the engine''s basis sentence say of unburned ethane and heavier?', '["They are counted as methane, one molecule a carbon atom.", "They are not methane and carry no GWP here.", "They carry the methane GWP.", "They pass through the flare as the CO2 in the gas does."]'::jsonb, 1, 'The basis sentence closes: "Unburned ethane and heavier are not methane and carry no GWP here." Only the methane in the gas enters the CH4 half of the rule.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 5, 'A gas that is all CO2 is flared at EGBEMA''s volume and days, with both efficiencies set to 0.5. What tonnes a year does the engine report?', '["CO2 133751.879, methane 1531.658", "CO2 140054.324, methane 1531.658", "CO2 182079.024, methane 1136.490", "CO2 140054.324, methane 0.000"]'::jsonb, 3, 'Both all-CO2 rows, at EGBEMA''s efficiencies and at 0.5, read 140054.324 and 0.000. 133751.879 and 1531.658 are the all-methane probe; 182079.024 and 1136.490 are EGBEMA''s flare.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 6, 'Which of the two efficiencies changes how much of the CO2 already in the gas leaves the flare as CO2?', '["Neither: it leaves as CO2 at every efficiency.", "The combustion efficiency, which sets the CO2.", "The destruction efficiency, which sets the share destroyed.", "Both, through the product of the two efficiencies."]'::jsonb, 0, 'The digest: "The CO2 already in the gas leaves the flare as CO2 at every efficiency, and none of it is methane." The all-CO2 probe reads 140054.324 t/yr at EGBEMA''s efficiencies and at both efficiencies 0.5.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 7, 'At what molar mass does the flare weigh its CO2 tonnes?', '["44.01, the reference table''s figure", "44.096, propane''s reference figure", "44.009 kg/kmol, from FLARE_MOLAR_MASS", "16.043 kg/kmol, from FLARE_MOLAR_MASS"]'::jsonb, 2, 'FLARE_MOLAR_MASS gives CO2 44.009 kg/kmol and methane 16.043 kg/kmol for the flare''s tonnes. The reference table carries CO2 at 44.01 for the gas''s mass and liquids; 44.096 is propane''s molar mass.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 8, 'EGBEMA''s call is run again with the combustion efficiency left out. Against the call with both given, what moves?', '["The methane moves by 2798.286 t/yr and the CO2 holds at 182079.024.", "The CO2 moves by 2798.286 t/yr and the methane holds at 1136.490.", "Both move: the CO2 by 2798.286 t/yr and the methane by 2798.285.", "Nothing moves: a missing combustion efficiency is refused."]'::jsonb, 1, 'The "left out minus given" row reads 0.0150, 2798.286, 0.000 and 2798.285. The stand-in moves the CO2 and leaves the methane where it was, because the methane is set by the destruction efficiency alone. 2798.285 is the CO2e difference.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 9, 'EGBEMA''s combustion efficiency is typed blank (''''). Which combustion efficiency does the engine use?', '["0.97, the destruction efficiency standing in, with a note", "0.955, the flare study''s figure, kept from the case", "0.955, set 1.5 points below the destruction efficiency", "None: the call is refused until a figure is typed"]'::jsonb, 0, 'The typed-blank row reads combustion efficiency used 0.97, the same as the row with it left out, and both rows carry the stand-in note. 0.955 is the figure the study gives when both are typed.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 10, 'With the combustion efficiency left out, what does EGBEMA''s flare give at a destruction efficiency of 1?', '["flareCo2Tonnes 188608.357 with flareCh4Tonnes 378.830", "flareCo2Tonnes 140054.324 with flareCh4Tonnes 0.000", "flareCo2Tonnes 190473.881 with flareCh4Tonnes 0.000", "flareCo2Tonnes 190473.881 with flareCh4Tonnes 378.830"]'::jsonb, 2, 'The destruction efficiency 1 row reads flareCo2Tonnes 190473.881, flareCh4Tonnes 0.000, flareCo2eTonnes 190473.881 and a methane share of 0.0000. 188608.357 and 378.830 is the 0.99 row; 140054.324 is the all-CO2 probe.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 11, 'In the destruction efficiency range (combustion left out), which input gives EGBEMA 3788.301 t of methane a year?', '["0.95", "0.99", "0.97", "0.9"]'::jsonb, 3, 'The range reads methane 3788.301 at 0.9, 1894.151 at 0.95, 1136.490 at 0.97, 378.830 at 0.99 and 0.000 at 1.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 12, 'Which efficiency does the digest define as the share oxidised to CO2?', '["The destruction efficiency, which sets the CO2", "The combustion efficiency, which sets the CO2", "The destruction efficiency, which sets the methane", "The combustion efficiency, which sets the methane"]'::jsonb, 1, 'The DESTRUCTION efficiency is the share of hydrocarbon destroyed and sets the methane. The COMBUSTION efficiency is the share oxidised to CO2 and sets the CO2. A combustion efficiency cannot exceed the destruction efficiency.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 13, 'In EGBEMA''s "left out minus given" row the CO2 reads 2798.286 and the CO2e 2798.285, with the methane at 0.000. What reason does the digest give?', '["Each tonnage is reported to three decimals before the difference is taken.", "The CO2e carries the methane at the GWP, and the methane moved slightly.", "The CO2e is formed at 0.955 and the CO2 at 0.97.", "The CO2e weighs its CO2 at 44.01 and the CO2 row at 44.009."]'::jsonb, 0, 'The rounding note: the engine reports each tonnage to three decimals before the difference is taken, so the CO2e difference and the CO2 difference can differ in the third decimal though the methane is the same.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 14, 'The analysis is set to pure methane and EGBEMA''s rate, days and flare study are kept. What comes back?', '["140054.324 t/yr CO2 beside 0.000 t/yr CH4", "133751.879 t/yr CO2 beside 1136.490 t/yr CH4", "182079.024 t/yr CO2 beside 1531.658 t/yr CH4", "133751.879 t/yr CO2 beside 1531.658 t/yr CH4"]'::jsonb, 3, 'The all-methane row reads flareCo2Tonnes 133751.879 and flareCh4Tonnes 1531.658. 140054.324 and 0.000 are the all-CO2 probe; 182079.024 and 1136.490 are EGBEMA''s gas.'),
  ('gasvalue', 'beginner', 'module', 'm04-the-flare-by-the-rule', 15, 'With both efficiencies given, 0.97 and 0.955, which tonnes of CO2 and of methane a year does EGBEMA''s flare report?', '["184877.310 and 1136.490", "182079.024 and 1136.490", "182079.024 and 2083.055", "215946.438 and 1136.490"]'::jsonb, 1, 'EGBEMA''s flare reads flareCo2Tonnes 182079.024 and flareCh4Tonnes 1136.490. 184877.310 is the CO2 with the combustion efficiency left out, 2083.055 is every unburned carbon counted as methane, and 215946.438 is the flare''s CO2e.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 1, 'EGBEMA''s flare is run with the methane GWP left blank. What comes back?', '["A refusal naming the missing GWP, with no tonnes of CO2, methane or CO2e reported at all", "CO2 182079.024 and methane 1136.490 t/yr, with the CO2e and the methane share both null", "CO2e 182079.024 t/yr with the methane counted at no GWP, and the methane share of the flare''s CO2e at 0.0000", "CO2e 215946.438 t/yr at a GWP of 29.8, taken as the engine''s default, with a note saying so"]'::jsonb, 1, 'The blank GWP table reads flareCo2Tonnes 182079.024, flareCh4Tonnes 1136.490, flareCo2eTonnes null, methaneShareOfFlareCo2e null and blockedBy "no methane global warming potential supplied". The methane GWP is an input with no default.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 2, 'At a methane GWP of 40, what flareCo2eTonnes does EGBEMA''s flare give?', '["204808.832", "215946.438", "218744.723", "227538.640"]'::jsonb, 3, 'The GWP table reads 227538.640 at 40, 204808.832 at 20 and 215946.438 at the study''s 29.8, the rows at 20 and 40 for comparison only. 218744.723 is the CO2e with the combustion efficiency left out.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 3, 'Read at the comparison GWP of 20, what share of EGBEMA''s flare CO2e is methane?', '["0.1998", "0.1568", "0.1548", "0.1110"]'::jsonb, 3, 'At 20 the share column prints 0.1110. 0.1998 sits at 40, 0.1568 at the study''s 29.8, and 0.1548 is the stand-in row at 0.97.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 4, 'How does the digest form methaneShareOfFlareCo2e?', '["flareCh4Tonnes over flareCo2eTonnes", "flareCh4Tonnes times the GWP over flareCo2Tonnes", "flareCh4Tonnes times the GWP over flareCo2eTonnes", "flareCh4Tonnes over flareCo2Tonnes"]'::jsonb, 2, 'methaneShareOfFlareCo2e is flareCh4Tonnes times the GWP over flareCo2eTonnes, 0.1568 on EGBEMA at 29.8. CO2e is the CO2 plus the methane times the GWP.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 5, 'abatement is called with a destruction efficiency of 1.2. What does it answer?', '["REFUSED: A flare destruction efficiency in (0, 1] is required. For a flare it is most of the answer and it is contested, so it is not assumed.", "REFUSED: A flare combustion efficiency must lie in (0, 1] and cannot exceed the destruction efficiency.", "It caps the efficiency at 1 and reports flareCh4Tonnes 0.000, as at a destruction efficiency of 1.", "REFUSED: A characterised gas is required."]'::jsonb, 0, 'The refusal table gives the destruction efficiency sentence for a blank and for 1.2 alike. The range it states is (0, 1].'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 6, 'EGBEMA''s call carries a combustion efficiency of 0.98 above a destruction efficiency of 0.97. What does abatement answer?', '["It cuts the combustion efficiency to 0.97 and says so in a note, as it does when the combustion efficiency is left out of the call.", "REFUSED: A flare destruction efficiency in (0, 1] is required. For a flare it is most of the answer and it is contested, so it is not assumed.", "It uses 0.98 as typed and reports a CO2 above EGBEMA''s 182079.024 t/yr.", "REFUSED: A flare combustion efficiency must lie in (0, 1] and cannot exceed the destruction efficiency."]'::jsonb, 3, 'The refusal table prints the combustion efficiency sentence for 0.98 above 0.97. A combustion efficiency cannot exceed the destruction efficiency.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 7, 'On-stream days are omitted from the call entirely, never typed. What does abatement do?', '["REFUSED: On-stream days are required, more than 0 and no more than 366.", "It takes the stated default, scfPerYear 2625000000", "It takes EGBEMA''s 355 days, scfPerYear 2662500000", "It takes the top of the range, 366 days"]'::jsonb, 1, 'On-stream days omitted from the call take the stated default, and scfPerYear reads 2625000000. Typed blank, they are refused.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 8, 'Which pair of on-stream days probes are both answered with the on-stream days sentence in abatement''s refusal table?', '["Days omitted from the call and days typed as 367", "Days typed blank ('''') and days omitted", "Days typed blank ('''') and days typed as 367", "Days typed as 355 and days typed as 367"]'::jsonb, 2, 'The table prints "REFUSED: On-stream days are required, more than 0 and no more than 366." for the blank, for 0 and for 367. Omitted days take the stated default (scfPerYear 2625000000), and EGBEMA''s 355 days are answered.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 9, 'Which of these calls does abatement answer with "REFUSED: A characterised gas is required."?', '["A call carrying no gas volume", "A call with on-stream days blank", "A call with the methane GWP blank", "A call on a gas the analysis refused"]'::jsonb, 3, 'The refusal table prints that sentence for a gas the analysis refused. No volume gets "REFUSED: A gas volume is required.", blank days get the on-stream days sentence, and a blank GWP is answered with the CO2e null.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 10, 'What does the digest say about a flare that is not lit?', '["It is not modelled; the engine''s flare is lit.", "It is modelled at destruction efficiency 0.5.", "It is modelled with its methane set by the combustion efficiency.", "It is modelled as vented gas, all of it methane."]'::jsonb, 0, 'Among the stated limits: an unlit flare is not modelled. Gas sent to a flare that is not lit is vented, all of it methane; the engine''s flare is lit.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 11, '40 CFR 98.233(n)(1) is a United States rule with tiered default pairs. What does the engine do with them?', '["It uses the rule''s first tier when a box is left blank.", "Neither efficiency takes a default; both stay inputs.", "It uses the NUPRC flare regulations'' basis when blank.", "It uses EGBEMA''s 0.97 and 0.955 as the defaults."]'::jsonb, 1, 'The stated limit: the efficiencies have no default. Whether a Nigerian flare study defaults to any tier, or to the NUPRC flare regulations'' basis, is a regulation reading, and both efficiencies stay inputs. The studio opens with both blank and abatement refuses.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 12, 'The digest shows the on-stream days default by asking one function with the days omitted. Which, and what does it report?', '["abatement, onstreamDays 355", "routeEconomics, onstreamDays 366", "routeEconomics, onstreamDays 350", "characteriseGas, onstreamDays 350"]'::jsonb, 2, 'SECTION 13: routeEconomics, asked with the days omitted, reports onstreamDays 350, and 7.5 MMscfd times a million times 350 is the omitted call''s scfPerYear.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 13, 'Which of these does the engine ship?', '["Typical component heating values and liquid densities", "A methane GWP, taken whenever the GWP box is left blank", "A credit price for the tonnes a route abates", "A default flare destruction efficiency"]'::jsonb, 0, 'The digest: the methane GWP and any credit price are case inputs, and the engine ships neither; the efficiencies have no default. The component heating values and liquid densities are the engine''s own labelled typical tables.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 14, 'EGBEMA at a destruction efficiency of 0.97 appears with a methane share of 0.1568 and of 0.1548. What separates the two rows?', '["The GWP: 29.8 against 20", "The methane in the flare: 1136.490 against 1531.658 t/yr", "The on-stream days: 355 against 350", "The combustion efficiency used: 0.955 against 0.97"]'::jsonb, 3, 'With both efficiencies given the combustion efficiency used is 0.955 and the share 0.1568. In the range, combustion is left out and stands in each time, and its 0.97 row prints 184877.310, 1136.490 and 218744.723, the same tonnes as EGBEMA''s call with the combustion efficiency left out, where 0.97 is the efficiency used; its share reads 0.1548. The share at a GWP of 20 is 0.1110.'),
  ('gasvalue', 'beginner', 'module', 'm05-co2e-and-its-limits', 15, 'Which term of CO2e does the methane GWP multiply?', '["The CO2 and the methane", "The CO2 alone", "The methane alone", "The methane and the unburned ethane and heavier"]'::jsonb, 2, 'CO2e is the CO2 plus the methane times the GWP, so the GWP sits on the methane term.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Which two lines of EGBEMA''s end-to-end table are the most any route can take out of a thousand standard cubic feet, by mass?', '["mass, kg/Mscf and propane and heavier, kg/Mscf", "liquids, gal/Mscf C3+ and richness", "heating value, Btu/scf and inerts, mole fraction", "flare CO2, t/yr and flare methane, t/yr"]'::jsonb, 0, 'SECTION 9 says of kgPerMscf and c3PlusKgPerMscf: they are the most any route can take out of a thousand standard cubic feet, by mass. On EGBEMA they read 26.7066 and 6.6647.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which line of the EGBEMA end-to-end table needs the methane GWP of 29.8?', '["flare CO2, 182079.024 t/yr", "flare methane, 1136.490 t/yr", "flare CO2e, 215946.438 t/yr", "hydrocarbon carbon per mole, 1.3320"]'::jsonb, 2, 'CO2e is the CO2 plus the methane times the GWP. With the GWP left blank the engine still reports flareCo2Tonnes 182079.024 and flareCh4Tonnes 1136.490, and flareCo2eTonnes reads null.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 3, 'The digest reads the studio''s opening gas the same way as EGBEMA. At which line does its table end?', '["flare CO2, t/yr", "flare CO2e, t/yr", "flare methane, t/yr", "richness, which reads rich"]'::jsonb, 3, 'The studio''s table runs from the heating value, 1210.7800 Btu/scf, to richness, rich. Its flare is refused until the efficiencies are typed.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What do the studio opening gas''s liquids line and richness line read?', '["5.0897 gal/Mscf C3+, rich", "2.6894 gal/Mscf C3+, rich", "2.6894 gal/Mscf C3+, moderate", "3.2205 gal/Mscf C3+, rich"]'::jsonb, 1, 'The studio''s table prints liquids 2.6894 and richness rich; 2.6894 is at or above the upper edge of 2.5000. 5.0897 is its gpmC2Plus and 3.2205 is EGBEMA''s liquids line.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Beside its analysis, which flare inputs does the digest give EGBEMA?', '["10 MMscfd, 350 days, 0.97, 0.955 and a GWP of 29.8", "7.5 MMscfd, 355 days, 0.97, 0.955 and a GWP of 20", "7.5 MMscfd, 350 days, 0.97, 0.97 and a GWP of 29.8", "7.5 MMscfd, 355 days, 0.97, 0.955 and a GWP of 29.8"]'::jsonb, 3, 'EGBEMA flares 7.5 MMscfd on 355 days a year; the flare study gives a destruction efficiency of 0.97 and a combustion efficiency of 0.955 and uses a methane GWP of 29.8. 10 MMscfd on 350 days is the studio''s opening parcel, and 20 is a comparison GWP.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Beside 215946.438, which methaneShareOfFlareCo2e does abatement print for EGBEMA at the study''s GWP?', '["0.1568", "0.1548", "0.1110", "0.2496"]'::jsonb, 0, 'methaneShareOfFlareCo2e reads 0.1568 on EGBEMA at 29.8 with both efficiencies given. 0.1548 is the share with the combustion efficiency left out, 0.1110 the share at a GWP of 20, and 0.2496 is EGBEMA''s c3PlusKgPerMscf over kgPerMscf.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 7, 'The studio gas''s end-to-end table opens on its heating value. Which figure, in Btu/scf?', '["1248.4110", "1210.7800", "1035.6050", "1308.6069"]'::jsonb, 1, 'SECTION 15''s studio table opens at 1210.7800; 1248.4110 opens EGBEMA''s.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Line one of EGBEMA''s table reads sheet sum 1.0000. What does the same sheet typed short report?', '["0.9850, with the analysis refused as incomplete", "1.0000, since the engine scales every sheet before the sum", "0.9850, with a note that the fractions were scaled to one", "0.9850, with the fractions carried on as typed"]'::jsonb, 2, 'rawMoleFractionSum reads 0.9850 on the sheet typed short and 1.0000 in full. Only the short sheet carries a normalisationNote, and its normalised C1 is 0.7411.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 9, 'The flare methane line reads 1136.490 t/yr. From which figure of EGBEMA''s gas does the rule start it?', '["methaneMoleFraction, 0.7420", "carbonPerMol, 1.3600, every carbon atom", "hydrocarbonCarbonPerMol, 1.3320", "co2MoleFraction, 0.0280"]'::jsonb, 0, 'CH4 = the methane in the gas times one less the destruction efficiency. Starting from carbonPerMol is the every-unburned-carbon shortcut, which gives 2083.055.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 10, 'The studio opens on its own gas at 10 MMscfd and 350 days. What must be typed before abatement returns a flare CO2?', '["A methane GWP, as the CO2 is blocked without one", "A gas volume, as the opening parcel carries none", "On-stream days, as the opening parcel carries none", "A destruction efficiency, the input its refusal names"]'::jsonb, 3, 'The studio opens with both efficiencies and the GWP blank, and its flare is refused until the efficiencies are typed: "REFUSED: A flare destruction efficiency in (0, 1] is required." A combustion efficiency left out is stood in for by the destruction efficiency, and a blank GWP leaves only the CO2e and the share null.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which EGBEMA figure is the end-to-end line "liquids, gal/Mscf C3+"?', '["5.9942", "3.2205", "2.6894", "6.6647"]'::jsonb, 1, 'EGBEMA''s liquids line reads 3.2205. 5.9942 is its gpmC2Plus, 2.6894 is the studio''s liquids line and 6.6647 is EGBEMA''s propane and heavier in kg/Mscf.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 12, 'In the studio''s gas, what are methaneMoleFraction and co2MoleFraction?', '["0.7420 methane, 0.0280 CO2", "0.9250 methane, 0.0150 CO2", "0.7800 methane, 0.0200 CO2", "0.7800 methane, 0.0400 CO2"]'::jsonb, 2, 'The studio''s opening gas reads methaneMoleFraction 0.7800 and co2MoleFraction 0.0200. 0.7420 and 0.0280 are EGBEMA, 0.9250 and 0.0150 are OGUTA, and 0.0400 is the studio gas''s inertMoleFraction.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which input of EGBEMA''s flare enters the flare CO2e line and neither the flare CO2 nor the flare methane line?', '["The methane GWP, 29.8", "The destruction efficiency, 0.97", "The combustion efficiency, 0.955", "The methane mole fraction, 0.7420"]'::jsonb, 0, 'CO2e is the CO2 plus the methane times the GWP; the destruction efficiency sets the methane and the combustion efficiency sets the CO2. With the GWP left blank the CO2 and the methane are still reported.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 14, 'EGBEMA is analysed with propane''s liquid density left blank. Which two end-to-end lines does the digest print as null on that probe?', '["The liquids line and the propane and heavier kg/Mscf", "The heating value line and the liquids line", "The richness line and the mass, kg/Mscf line", "The liquids line and the richness line"]'::jsonb, 3, 'SECTION 8''s probe row prints gpmC3Plus null and richness null beside ghvBtuScf 1248.4110. SECTION 9 prints c3PlusKgPerMscf 6.6647 and kgPerMscf 26.7066 on the same probe.'),
  ('gasvalue', 'beginner', 'module', 'm06-the-associate-reading', 15, 'On the studio''s opening gas, which figure counts only the carbon that can burn, per mole?', '["1.3000", "1.2800", "1.3320", "1.0430"]'::jsonb, 1, 'hydrocarbonCarbonPerMol reads 1.2800 on the studio''s opening gas and carbonPerMol 1.3000. 1.3320 is EGBEMA''s hydrocarbon carbon per mole and 1.0430 is OGUTA''s.'),
  ('gasvalue', 'beginner', 'final', null, 1, 'Which function do the studios use to answer "what does the flare emit, and what does recovering it abate"?', '["characteriseGas", "abatement", "compareRoutes", "creditSensitivity"]'::jsonb, 1, 'abatement is the function paired with the flare''s emissions and what recovering the flare abates.'),
  ('gasvalue', 'beginner', 'final', null, 2, 'Which exported constant holds 7.480519?', '["GAL_PER_FT3", "SCF_PER_LBMOL", "LB_PER_KG", "M3_PER_SCF"]'::jsonb, 0, 'The constants table: GAL_PER_FT3, 7.480519, US gallons in one cubic foot.'),
  ('gasvalue', 'beginner', 'final', null, 3, 'In the digest''s arithmetic for kgPerMscf, which constant turns pounds into kilograms?', '["SCF_PER_LBMOL, 379.49", "GAL_PER_FT3, 7.480519", "LB_PER_KG, 2.20462262", "PSI_PER_BAR, 14.503773773"]'::jsonb, 2, 'The kilograms are the pounds over LB_PER_KG, pounds in one kilogram. SCF_PER_LBMOL gives the lb-mol in one Mscf (1000 over it), GAL_PER_FT3 is gallons in a cubic foot and PSI_PER_BAR is lpgCng''s psi in one bar.'),
  ('gasvalue', 'beginner', 'final', null, 4, 'The digest recomputes kgPerMscf for pure methane and pure carbon dioxide from the constants, beside the engine. What does its difference column read?', '["0.0000 on methane, with the CO2 row left to the engine", "19.1757 on methane and 52.6038 on carbon dioxide", "0.0000 on methane, the CO2 row weighed at 44.009", "0.0000 on both rows"]'::jsonb, 3, 'The check table prints 19.1757 against 19.1757 for methane and 52.6038 against 52.6038 for carbon dioxide, with 0.0000 in the difference column on both.'),
  ('gasvalue', 'beginner', 'final', null, 5, 'Iso-butane and n-butane share a molar mass of 58.122 lb/lbmol. Where do their reference rows differ?', '["In the carbon per molecule, 4 against 5", "In the recoverable as NGL flag", "In the inert flag and the heating value", "In the typical heating value and the liquid density"]'::jsonb, 3, 'IC4 reads 3252 Btu/scf and 4.695 lb/gal; NC4 reads 3263 and 4.872. Both carry 4 carbon per molecule, both are recoverable as NGL and neither is inert.'),
  ('gasvalue', 'beginner', 'final', null, 6, 'What liquid density does GAS_COMPONENT_REFERENCE give propane?', '["2.971 lb/gal", "4.233 lb/gal", "4.695 lb/gal", "5.253 lb/gal"]'::jsonb, 1, 'Propane''s row reads 4.233 lb/gal. 2.971 is ethane, 4.695 iso-butane and 5.253 pentanes plus. The engine''s note labels these densities typical.'),
  ('gasvalue', 'beginner', 'final', null, 7, 'EGBEMA''s sheet typed short gets a normalisation note. What does the note end by asking?', '["Check the analysis if that was not intended.", "Retype the sheet so that it sums to one.", "Add the shortfall to the methane row, then rerun.", "Confirm the scaled sheet against the laboratory."]'::jsonb, 0, 'The note''s second sentence is the request: "Check the analysis if that was not intended." The first reports the raw sum.'),
  ('gasvalue', 'beginner', 'final', null, 8, 'OGUTA is the lean non-associated gas. Which ghvBtuScf does the digest print for it?', '["1248.4110", "1035.6050", "1210.7800", "1010"]'::jsonb, 1, 'OGUTA''s ghvBtuScf is 1035.6050. 1248.4110 is EGBEMA, 1210.7800 the studio''s opening gas and 1010 is methane''s typical heating value in the reference table.'),
  ('gasvalue', 'beginner', 'final', null, 9, 'What does the digest print as OGUTA''s inertMoleFraction, and from which fractions?', '["0.0150, from CO2 0.0150 alone", "0.0270, from N2 0.0120 plus CO2 0.0150", "0.0460, from N2 0.0180 plus CO2 0.0280", "0.0400, from N2 0.0200 plus CO2 0.0200"]'::jsonb, 1, 'The inert table''s OGUTA row sums its two inert codes to 0.0270, and the engine agrees.'),
  ('gasvalue', 'beginner', 'final', null, 10, 'molarMassLbLbmol reads 22.3436 for one gas. Which, and what does one Mscf of it weigh?', '["OGUTA, carrying 21.0224 kg in one Mscf", "The studio''s gas, carrying 25.4954 kg in one Mscf", "Pure propane, carrying 52.7066 kg in one Mscf", "EGBEMA, carrying 26.7066 kg in one Mscf"]'::jsonb, 3, 'EGBEMA''s row pairs 22.3436 lb/lbmol with 26.7066 kg/Mscf; each of the other three pairs is another gas''s row.'),
  ('gasvalue', 'beginner', 'final', null, 11, 'What carbonPerMol does characteriseGas give OGUTA?', '["1.0430", "1.3600", "1.3000", "1.0580"]'::jsonb, 3, 'SECTION 5 prints OGUTA at carbonPerMol 1.0580; 1.0430 is its hydrocarbon count, and the other two are EGBEMA and the studio gas.'),
  ('gasvalue', 'beginner', 'final', null, 12, 'A sheet is typed with every mole fraction zero. What does characteriseGas answer?', '["REFUSED: Every component needs a mole fraction.", "REFUSED: A mole fraction cannot be negative.", "REFUSED: The gas composition sums to nothing.", "A note that the fractions were scaled to one."]'::jsonb, 2, 'The refusal table prints "REFUSED: The gas composition sums to nothing." for every mole fraction zero. The blank mole fraction and the negative mole fraction each get their own sentence.'),
  ('gasvalue', 'beginner', 'final', null, 13, 'EGBEMA''s short sheet types CO2 as 0.028. At which fraction does the scaled sheet carry it?', '["0.0284", "0.0280", "0.0183", "0.0213"]'::jsonb, 0, 'The normalised short-sheet column reads CO2 0.0284. 0.0280 is the full sheet''s normalised CO2, and 0.0183 and 0.0213 are the short sheet''s N2 and NC4.'),
  ('gasvalue', 'beginner', 'final', null, 14, 'Two EGBEMA calls: one with the destruction efficiency blank, one with the GWP blank. How does abatement answer them?', '["The blank efficiency is refused; the blank GWP leaves the CO2e null", "The blank efficiency leaves the methane null; the blank GWP is refused", "Each is refused, with its own REFUSED sentence", "Each is answered, with one figure left null"]'::jsonb, 0, 'A blank destruction efficiency gets "REFUSED: A flare destruction efficiency in (0, 1] is required." and more. With the GWP blank the CO2 and methane print and the CO2e reads null.'),
  ('gasvalue', 'beginner', 'final', null, 15, 'characteriseGas meets a blank liquid density in one sheet and a blank mole fraction in another. What happens to each?', '["The density is refused; the blank fraction is scaled away with a note", "The liquids go null for the density; the blank fraction is refused", "Both are refused, each in a sentence of its own", "Both are answered, the sheet scaled to one first"]'::jsonb, 1, 'Propane''s density blank returns gpmC2Plus, gpmC3Plus and richness null with missingLiquidDensity C3. A blank mole fraction gets "REFUSED: Every component needs a mole fraction."'),
  ('gasvalue', 'beginner', 'final', null, 16, 'The combustion efficiency is left out of one call; the destruction efficiency is typed blank in another. What does abatement do?', '["Missing combustion is refused; combustion stands in for blank destruction", "Both calls are refused, since neither efficiency has a default", "Each efficiency stands in for the other, with a note on both calls", "Destruction stands in for the missing combustion; blank destruction is refused"]'::jsonb, 3, 'Left out, the destruction efficiency stands in for the combustion efficiency and the engine says so in a note. A blank destruction efficiency is refused: "For a flare it is most of the answer and it is contested, so it is not assumed."'),
  ('gasvalue', 'beginner', 'final', null, 17, 'On-stream days are omitted in one call and typed blank in another. How does abatement treat the two?', '["Omitted days are refused; blank days take the default, scfPerYear 2625000000", "Omitted days take the default, scfPerYear 2625000000; blank days are refused", "Either way the default applies, and scfPerYear reads 2625000000", "Either way the call is refused with the on-stream days sentence"]'::jsonb, 1, 'SECTION 13: omitted from the call, the days take the stated default (onstreamDays 350). Typed blank (''''), they are refused with the range more than 0 and no more than 366.'),
  ('gasvalue', 'beginner', 'final', null, 18, 'Propane''s carbon number is left blank in one analysis and an unknown code, XX, carries none in another. What does characteriseGas do with each?', '["Propane''s is refused; XX is filled from the reference by its code", "Propane''s is filled from the reference by its code; XX is refused", "Both are refused, since a carbon number is never assumed", "Both are filled, at one carbon per molecule each"]'::jsonb, 1, 'The propane probe reads carbonPerMol 1.2000 with the carbon number typed and with it blank. XX has no reference row: "REFUSED: No carbon number for XX."'),
  ('gasvalue', 'beginner', 'final', null, 19, 'From which carbon count does the digest''s every-unburned-carbon methane shortcut start?', '["hydrocarbonCarbonPerMol, only the carbon that can burn", "methaneMoleFraction, the methane in the gas", "The ethane and heavier carbon alone", "carbonPerMol, every carbon atom, the CO2''s included"]'::jsonb, 3, 'The shortcut multiplies the lb-mol a year by carbonPerMol, every carbon atom with the CO2''s included.'),
  ('gasvalue', 'beginner', 'final', null, 20, 'What typical heating value does GAS_COMPONENT_REFERENCE give methane, in Btu/scf?', '["1770", "2516", "0", "1010"]'::jsonb, 3, 'The C1 row reads 1010. 1770 is ethane, 2516 propane, and 0 is the figure on the two inert rows, N2 and CO2.'),
  ('gasvalue', 'beginner', 'final', null, 21, 'In the destruction efficiency range (combustion left out), which methaneShareOfFlareCo2e sits at 0.99?', '["0.2376", "0.0565", "0.1548", "0.1110"]'::jsonb, 1, 'The range reads methaneShareOfFlareCo2e 0.2376 at 0.95, 0.1548 at 0.97, 0.0565 at 0.99 and 0.0000 at 1. 0.1110 is the share at the comparison GWP of 20, with both efficiencies given.'),
  ('gasvalue', 'beginner', 'final', null, 22, 'In the digest''s words, what is the destruction efficiency?', '["The share oxidised to CO2", "The share of the gas sent to an unlit flare", "The share of hydrocarbon destroyed", "The share of the CO2 that passes through"]'::jsonb, 2, 'SECTION 11 defines it as the share of hydrocarbon destroyed; its partner is the share oxidised to CO2.'),
  ('gasvalue', 'beginner', 'final', null, 23, 'The destruction efficiency stands in at 0.97 on EGBEMA. Which CO2e comes back?', '["215946.438", "237591.952", "218744.723", "199897.495"]'::jsonb, 2, 'With the destruction efficiency standing in at 0.97, flareCo2eTonnes reads 218744.723. 215946.438 is with both efficiencies given; 237591.952 and 199897.495 are the 0.95 and 0.99 rows of the range.'),
  ('gasvalue', 'beginner', 'final', null, 24, 'Whose choice does the digest say the assessment report behind a methane GWP is?', '["The engine''s, which ships a default", "The study''s", "The course''s, which picks one edition", "40 CFR 98.233(n)''s, which the engine follows"]'::jsonb, 1, 'The methane GWP is an input with no default: the assessment report it comes from is the study''s to choose, and this course does not choose it. The engine ships no GWP.'),
  ('gasvalue', 'beginner', 'final', null, 25, 'EGBEMA flares 7.5 MMscfd. What scfPerYear does the engine report for its flare as typed?', '["2625000000, on 355 days", "2625000000, on the 350-day default", "2662500000, on 355 days", "2662500000, on the 350-day default"]'::jsonb, 2, 'EGBEMA flares on 355 days and its scfPerYear is 2662500000. 2625000000 is the call with the on-stream days omitted, which takes the stated default of 350.'),
  ('gasvalue', 'beginner', 'final', null, 26, 'Which ethane figure, gpmC2Plus minus gpmC3Plus, belongs to the studio''s gas?', '["2.4003", "2.7737", "0.8268", "2.6894"]'::jsonb, 0, '2.4003 is the studio row of SECTION 7''s ethane column. 2.6894 is that gas''s gpmC3Plus.'),
  ('gasvalue', 'beginner', 'final', null, 27, 'What does the sum row of EGBEMA''s per-component gallons print?', '["5.0897 for gpmC2Plus and 2.6894 for gpmC3Plus", "5.9942 for gpmC3Plus and 3.2205 for gpmC2Plus", "5.9942 for gpmC2Plus and 3.2205 for gpmC3Plus", "2.7737 for gpmC2Plus and 3.2205 for gpmC3Plus"]'::jsonb, 2, 'The sum row reads 5.9942 (gpmC2Plus), 3.2205 (gpmC3Plus). 5.0897 and 2.6894 are the studio''s opening gas, and 2.7737 is the C2 row.'),
  ('gasvalue', 'beginner', 'final', null, 28, 'EGBEMA''s ethane row gives 2.7737 gal/Mscf. Which liquid cut holds it?', '["gpmC3Plus only", "Both gpmC2Plus and gpmC3Plus", "gpmC2Plus only", "Neither, as ethane reads recoverable false"]'::jsonb, 2, 'The C2 row reads recoverable true, in gpmC2Plus true and in gpmC3Plus false, at 2.7737. The digest prints the same figure as gpmC2Plus minus gpmC3Plus, the ethane.'),
  ('gasvalue', 'beginner', 'final', null, 29, 'Which figure is OGUTA''s c3PlusKgPerMscf, the propane and heavier part of its mass?', '["0.4890", "1.3157", "0.9798", "0.8268"]'::jsonb, 2, 'OGUTA''s c3PlusKgPerMscf is 0.9798 kg. 0.4890 is its gpmC3Plus in gallons, 1.3157 its gpmC2Plus and 0.8268 its ethane in gallons.'),
  ('gasvalue', 'beginner', 'final', null, 30, 'What does the ghvNote read when a component''s heating value is missing?', '["A heating value missing on any component leaves the mixture value missing too. No partial average is reported.", "A heating value missing on any component is taken at 0 Btu/scf, as an inert''s is, and the mixture is averaged over the rest.", "A heating value missing on any component is taken from the reference by its code, and the mixture is reported as typed.", "A heating value missing on any component is refused. Every component needs a heating value."]'::jsonb, 0, 'The n-butane heating value probe prints ghvBtuScf null with that note. Its liquids still read 5.9942 and 3.2205 gal/Mscf.'),
  ('gasvalue', 'beginner', 'final', null, 31, 'Which reference row carries one carbon per molecule and is marked inert?', '["CO2", "C1", "N2", "C2"]'::jsonb, 0, 'CO2 carries 1 carbon per molecule and inert true. C1 carries 1 and is not inert; N2 is inert with 0 carbon; C2 carries 2 and is not inert.'),
  ('gasvalue', 'beginner', 'final', null, 32, 'Which export gives the molar masses the flare''s tonnes are weighed at?', '["GAS_COMPONENT_REFERENCE", "FLARE_MOLAR_MASS", "RICHNESS_GPM", "SCF_PER_LBMOL"]'::jsonb, 1, 'FLARE_MOLAR_MASS is one of flareToValue''s 10 exported constants and tables. GAS_COMPONENT_REFERENCE holds the component rows, RICHNESS_GPM the richness edges and SCF_PER_LBMOL the cubic feet in one lb-mol.'),
  ('gasvalue', 'beginner', 'final', null, 33, 'What does BTU_PER_MWH count?', '["Kilojoules in one kilowatt hour", "Btu in one standard cubic foot of the gas", "Psi in one bar", "International Table Btu in one megawatt hour"]'::jsonb, 3, 'BTU_PER_MWH is 3412141.6331 International Table Btu in one megawatt hour. Kilojoules in one kilowatt hour is lpgCng''s KJ_PER_KWH, 3600, and psi in one bar is PSI_PER_BAR.'),
  ('gasvalue', 'beginner', 'final', null, 34, 'Which functions answer "how much LPG can the vessel hold, and when to reorder"?', '["vaporizerDuty, bottlingPlant, assetFloat", "gasMassInVessel, cascadeFills", "cngCompression, cngDispensing", "lpgBlendProperties, lpgStorageSizing"]'::jsonb, 3, 'The table of questions pairs the vessel and its reorder with lpgBlendProperties and lpgStorageSizing. vaporizerDuty, bottlingPlant and assetFloat answer the vaporizer, carousel and cylinders; gasMassInVessel and cascadeFills the bank and cascade; cngCompression and cngDispensing the compressor and forecourt.'),
  ('gasvalue', 'beginner', 'final', null, 35, 'The digest names one module flareToValue draws on. Which, and for what?', '["terminalDepot, for its loading-rack queue", "production/gasProperties, for the Z factor", "modularRefinery, for capital by the power law", "facilities/compression, for its compressors"]'::jsonb, 2, 'flareToValue scales capital with the power law in modularRefinery. terminalDepot, production/gasProperties and facilities/compression are the three modules the digest names lpgCng calling.'),
  ('gasvalue', 'beginner', 'final', null, 36, 'When the destruction efficiency stands in for the combustion efficiency, what does the engine''s note say about the CO2?', '["It is slightly high, as the rule puts combustion 1.5 points below destruction.", "It is slightly low, as the rule puts combustion 1.5 points above destruction.", "It is exact, since the rule sets the two efficiencies equal for a flare.", "It is left null until a combustion efficiency is typed into the call."]'::jsonb, 0, 'The note: "No combustion efficiency was given, so the destruction efficiency stands in for it. 40 CFR 98.233(n) puts combustion 1.5 points below destruction, so the CO2 here is slightly high."'),
  ('gasvalue', 'beginner', 'final', null, 37, 'Which pair of efficiencies does abatement accept?', '["Destruction 0.97 and combustion 0.98", "Destruction 1.2 and combustion 0.955", "Destruction blank and combustion 0.955", "Destruction 0.97 and combustion 0.955"]'::jsonb, 3, 'EGBEMA''s flare study, 0.97 and 0.955, is answered. A combustion efficiency of 0.98 above 0.97 is refused, and a destruction efficiency of 1.2 or blank gets the destruction efficiency refusal.'),
  ('gasvalue', 'beginner', 'final', null, 38, 'Which on-stream days does abatement accept?', '["355", "367", "0", "blank ('''')"]'::jsonb, 0, 'EGBEMA''s 355 days are answered, scfPerYear 2662500000. The refusal states the range, more than 0 and no more than 366, and 0, 367 and a blank are all refused in the digest''s table.'),
  ('gasvalue', 'beginner', 'final', null, 39, 'Which of these does the digest state as a limit of the flare model?', '["An unlit flare is not modelled.", "A gas that carries CO2 is not modelled.", "A gas that carries nitrogen is not modelled.", "A combustion efficiency below the destruction efficiency is not modelled."]'::jsonb, 0, 'The stated limits: the efficiencies have no default, an unlit flare is not modelled, the GWP and credit prices are case inputs, and the reference figures are typical. EGBEMA carries N2 0.018 and CO2 0.028 and a combustion efficiency of 0.955 below its 0.97, and is answered.'),
  ('gasvalue', 'beginner', 'final', null, 40, 'On the Flare Gas to Value Studio''s opening flare, which parcel does the digest run?', '["7.5 MMscfd on 355 days", "10 MMscfd on 355 days", "10 MMscfd on 350 days", "7.5 MMscfd on 350 days"]'::jsonb, 2, 'The studio''s opening gas is run at 10 MMscfd and 350 days with the efficiencies blank, and abatement refuses. 7.5 MMscfd on 355 days is EGBEMA.'),
  ('gasvalue', 'beginner', 'final', null, 41, 'Which record does the digest describe as a flow station in Imo State flaring associated gas?', '["EGBEMA", "OGUTA", "KANO", "IBAFO"]'::jsonb, 0, 'EGBEMA is the flow station flaring associated gas. OGUTA is a lean non-associated gas, KANO an LPG storage and bottling plant and IBAFO a CNG mother station. Every record is invented; the places are real.'),
  ('gasvalue', 'beginner', 'final', null, 42, 'What does the digest say of EGBEMA''s efficiencies, 0.97 and 0.955?', '["They are the tiered default pair of 40 CFR 98.233(n)(1).", "They are invented and illustrative, as every efficiency in the digest is.", "They are the NUPRC flare regulations'' basis for Imo State.", "They were measured on the Egbema flare by the flare study."]'::jsonb, 1, 'The digest''s preamble: every analysis, efficiency, GWP, price, cost, fill limit and vehicle figure is invented and illustrative, and no figure is a measured flare or a regulation.');
